function clipToBox(ctx2, state2) {
  const gt = state2.entities.find((e) => e.alive && e.type.name === "obj_growtangle");
  if (!gt) return false;
  const hw = (gt.image_xscale ?? 2) * 37.5;
  const hh = (gt.image_yscale ?? 2) * 37.5;
  const minx = gt.x - hw + 5 + 4;
  const miny = gt.y - hh + 5 + 4;
  const maxx = gt.x + hw - 4 - 4;
  const maxy = gt.y + hh - 4 - 4;
  ctx2.save();
  ctx2.beginPath();
  ctx2.rect(minx - state2.view.x, miny - state2.view.y, maxx - minx, maxy - miny);
  ctx2.clip();
  return true;
}
